import{missions,launchers,timeline,achievements,timelineCategories}from"./data.js";import{TabNav}from"./components/TabNav.js";import{MissionCard,MissionDetail}from"./components/MissionCard.js";import{LauncherCard}from"./components/LauncherCard.js";import{TimelineView}from"./components/TimelineView.js";import{AchievementGrid}from"./components/AchievementGrid.js";const TABS=[{id:"overview",label:"Overview"},{id:"chandrayaan",label:"Chandrayaan"},{id:"mars-solar",label:"Mars & Solar"},{id:"gaganyaan",label:"Gaganyaan"},{id:"launchers",label:"Launchers"},{id:"timeline",label:"Timeline"},{id:"achievements",label:"Achievements"}];let activeTab="overview";function renderTabNav(){document.getElementById("isro-tab-nav-root").innerHTML=TabNav(TABS,activeTab)}function renderContent(){const e=document.getElementById("isro-tab-content-root");e.style.opacity="0",setTimeout(()=>{e.innerHTML=getTabContent(activeTab),attachListeners(),e.style.opacity="1"},150)}function getTabContent(e){switch(e){case"overview":return renderOverview();case"chandrayaan":return renderMissionsTab("chandrayaan");case"mars-solar":return renderMissionsTab("mars-solar");case"gaganyaan":return renderMissionsTab("gaganyaan");case"launchers":return renderLaunchersTab();case"timeline":return TimelineView(timeline,timelineCategories);case"achievements":return AchievementGrid(achievements);default:return""}}function renderOverview(){const e=missions.length,n=launchers.length;return`\n        <div class="isro-overview">\n            <div class="overview-hero">\n                <div class="overview-hero-content">\n                    <h2>Indian Space Research Organisation</h2>\n                    <p>Since 1962, ISRO has transformed India into a space power, achieving milestones that rival the world's most established space agencies — all at a fraction of the cost.</p>\n                </div>\n                <div class="overview-stats">\n                    <div class="overview-stat">\n                        <span class="os-number">${e}</span>\n                        <span class="os-label">Missions</span>\n                    </div>\n                    <div class="overview-stat">\n                        <span class="os-number">${missions.filter(e=>e.status.includes("Success")||e.status.includes("Operational")).length}</span>\n                        <span class="os-label">Successful</span>\n                    </div>\n                    <div class="overview-stat">\n                        <span class="os-number">${n}</span>\n                        <span class="os-label">Launch Vehicles</span>\n                    </div>\n                    <div class="overview-stat">\n                        <span class="os-number">60+</span>\n                        <span class="os-label">Years</span>\n                    </div>\n                </div>\n            </div>\n\n            <div class="overview-highlights">\n                <h3>Major Missions</h3>\n                <div class="overview-missions-list">${missions.slice(0,4).map(e=>`\n            <div class="overview-mission-item">\n                <span class="om-status ${e.status.toLowerCase().includes("success")?"success":e.status.toLowerCase().includes("operational")?"operational":e.status.toLowerCase().includes("planned")?"planned":"active"}"></span>\n                <div>\n                    <strong>${e.name}</strong>\n                    <span class="om-date">${e.launchDate.split(" ").slice(-2).join(" ")}</span>\n                </div>\n            </div>\n        `).join("")}</div>\n            </div>\n\n            <div class="overview-quick-launchers">\n                <h3>Launch Vehicles</h3>\n                <div class="overview-launcher-badges">\n                    ${launchers.map(e=>`\n                        <div class="olb-item" style="--lb-color: ${e.color}">\n                            <span class="olb-name">${e.name}</span>\n                            <span class="olb-type">${e.type}</span>\n                            <span class="olb-rate">${e.successRate} success</span>\n                        </div>\n                    `).join("")}\n                </div>\n            </div>\n        </div>\n    `}function renderMissionsTab(e){const n=missions.filter(n=>n.category===e);if(0===n.length)return'<div class="no-results">No missions found.</div>';return`\n        <div class="isro-missions-grid">\n            ${n.map((e,n)=>MissionCard(e,n)).join("")}\n        </div>\n    `}function renderLaunchersTab(){return`<div class="isro-launchers-grid">${launchers.map(e=>LauncherCard(e)).join("")}</div>`}function attachListeners(){document.querySelectorAll(".mission-expand-btn").forEach(e=>{e.addEventListener("click",()=>{const n=parseInt(e.dataset.index),s=missions.filter(e=>e.category===activeTab)[n];if(!s)return;const a="true"===e.getAttribute("aria-expanded"),i=e.closest(".isro-mission-card");if(a){const n=i.querySelector(".mission-detail-panel");n&&n.remove(),e.setAttribute("aria-expanded","false"),e.querySelector("span").textContent="Explore Mission",e.classList.remove("expanded")}else{const n=document.createElement("div");n.className="mission-detail-panel",n.innerHTML=MissionDetail(s),i.appendChild(n),e.setAttribute("aria-expanded","true"),e.querySelector("span").textContent="Collapse",e.classList.add("expanded")}})})}document.addEventListener("DOMContentLoaded",()=>{document.getElementById("isro-explorer-app").innerHTML='\n        <div id="isro-tab-nav-root"></div>\n        <div id="isro-tab-content-root"></div>\n    ',renderTabNav(),renderContent(),document.getElementById("isro-tab-nav-root").addEventListener("click",e=>{const n=e.target.closest(".isro-tab-btn");n&&(activeTab=n.dataset.tab,renderTabNav(),renderContent())})});